  function selectFleet(id:string,center=true){setInteraction('navy');setEditing(null);const r=runRef.current;if((!r||(r.version!==3&&r.version!==4&&r.version!==5&&r.version!==6&&(r.version!==7&&r.version!==8))))return;const f=r.navy.fleets.find(f=>f.id===id&&f.status!=='lost');if(!f){setFleetId(null);setSeaPreview([]);return;}setTargeting(false);setTargetId(null);setArmyId(null);setFleetId(id);setNationId(f.nationId);setPanel('navy');if(center)focus(motion.current.frame(performance.now()).fleets.get(f.id)??fleetPosition(graphFor(r),f));setNotice('已选舰队；预览海路后确认出航。');}
