  function locate(location:EventLocation){const r=runRef.current;if(!r)return;setTargeting(false);if(location.kind==='army-current'){selectArmy(location.id);return;}const p=namedWorld(r.world).provinces.find(p=>p.id===location.id);if(!p)return;setProvinceId(p.id);focus(p.center);setNotice(`${location.label}：${p.name}。当前地图已高亮。`);}
